/// Renders the hunt's outcome notifications.
///
/// **Pure functions**, like the reminder composers: the message the user reads
/// is the deliverable of this subsystem, so it is generated by a pure function
/// and asserted directly in tests rather than verified by eyeballing a
/// rendered notification.
///
/// ## Why the success notification is not optimistic
///
/// A basket purchase is **irreversible** — there is no cancel, no refund, no
/// way to give it back. So the notification is posted only once the outcome
/// is *known*: a confirmed purchase, or a reconciliation that established the
/// purchase landed. An ambiguous claim produces no success notification,
/// because it may not have been a purchase at all, and a notification that
/// says "bought" when nothing was bought is worse than silence — the student
/// would go looking for a meal they do not have.
library;

import 'models.dart';
import 'persian.dart';

/// A rendered notification: a title, a body, and a one-line summary.
class HuntNotification {
  const HuntNotification({
    required this.title,
    required this.body,
    this.summary,
  });

  final String title;
  final String body;

  /// The line the notification shade shows when the body is collapsed.
  final String? summary;

  @override
  String toString() => 'HuntNotification($title)';
}

/// Renders the notification for a successful purchase.
///
/// The message names the meal, the date, the hall and the amount, in the same
/// Persian format as the reminder notifications, so the two are visually
/// consistent.
HuntNotification composeHuntSuccess({
  required MealSlot slot,
  required DateTime date,
  required String dishName,
  required String hallName,
  required int priceRial,
}) {
  final buffer = StringBuffer()
    ..write('${mealSlotPersian(slot)} ${formatPersianDate(date)}')
    ..write(' — $dishName')
    ..write(' — $hallName')
    ..write('\nمبلغ: ${formatTomanPersian(priceRial)}');

  return HuntNotification(
    title: '🌙 خرید موفق',
    body: buffer.toString(),
    summary: '${mealSlotPersian(slot)} ${formatPersianDate(date)} — $dishName',
  );
}

/// Renders the notification for a hunt that ended without buying.
///
/// The reason is stated plainly, because "nothing happened" is the message a
/// student most needs explained: a hunt that found nothing is normal, and a
/// hunt that was refused is not.
HuntNotification composeHuntEnded({
  required String reason,
  String? title,
}) =>
    HuntNotification(
      title: title ?? '🔎 شکار تمام شد',
      body: 'شکار بدون خرید به پایان رسید.\n$reason',
    );

/// The meal slot's name, in the portal's own words.
String mealSlotPersian(MealSlot slot) {
  switch (slot) {
    case MealSlot.breakfast:
      return 'صبحانه';
    case MealSlot.lunch:
      return 'ناهار';
    case MealSlot.dinner:
      return 'شام';
  }
}
